CREATE TABLE IF NOT EXISTS `users` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`email` text NOT NULL,`password_hash` text NOT NULL,`role` text DEFAULT 'voter' NOT NULL,`display_name` text NOT NULL,`phone` text,`status` text DEFAULT 'active' NOT NULL,`last_login_at` integer,`created_at` integer NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `users_email_unique` ON `users` (`email`);
CREATE TABLE IF NOT EXISTS `sessions` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`token_hash` text NOT NULL,`user_id` integer NOT NULL,`expires_at` integer NOT NULL,`created_at` integer NOT NULL,FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `sessions_token_hash_unique` ON `sessions` (`token_hash`);
CREATE TABLE IF NOT EXISTS `categories` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`name` text NOT NULL,`slug` text NOT NULL,`description` text DEFAULT '' NOT NULL,`cover_key` text,`display_order` integer DEFAULT 0 NOT NULL,`active` integer DEFAULT true NOT NULL,`created_at` integer NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `categories_slug_unique` ON `categories` (`slug`);
CREATE TABLE IF NOT EXISTS `contestant_accounts` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`user_id` integer NOT NULL,`contestant_id` integer NOT NULL,`created_at` integer NOT NULL,FOREIGN KEY (`user_id`) REFERENCES `users`(`id`),FOREIGN KEY (`contestant_id`) REFERENCES `contestants`(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `contestant_accounts_user_id_unique` ON `contestant_accounts` (`user_id`);
CREATE UNIQUE INDEX IF NOT EXISTS `contestant_accounts_contestant_id_unique` ON `contestant_accounts` (`contestant_id`);
CREATE TABLE IF NOT EXISTS `video_submissions` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`contestant_id` integer NOT NULL,`event_id` integer,`round_id` integer,`storage_key` text NOT NULL,`filename` text NOT NULL,`content_type` text NOT NULL,`size` integer NOT NULL,`title` text NOT NULL,`caption` text DEFAULT '' NOT NULL,`status` text DEFAULT 'pending' NOT NULL,`admin_note` text,`created_at` integer NOT NULL,`reviewed_at` integer,`published_at` integer,FOREIGN KEY (`contestant_id`) REFERENCES `contestants`(`id`),FOREIGN KEY (`event_id`) REFERENCES `events`(`id`),FOREIGN KEY (`round_id`) REFERENCES `voting_rounds`(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `video_submissions_storage_key_unique` ON `video_submissions` (`storage_key`);
CREATE TABLE IF NOT EXISTS `video_consents` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`video_id` integer NOT NULL,`contestant_id` integer NOT NULL,`version` text NOT NULL,`consent_text` text NOT NULL,`session_metadata` text,`created_at` integer NOT NULL,FOREIGN KEY (`video_id`) REFERENCES `video_submissions`(`id`),FOREIGN KEY (`contestant_id`) REFERENCES `contestants`(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `video_consents_video_id_unique` ON `video_consents` (`video_id`);
CREATE TABLE IF NOT EXISTS `payment_methods` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`name` text NOT NULL,`code` text NOT NULL,`enabled` integer DEFAULT false NOT NULL,`configured` integer DEFAULT false NOT NULL,`status` text DEFAULT 'not_configured' NOT NULL,`created_at` integer NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `payment_methods_code_unique` ON `payment_methods` (`code`);
